def forced_order(n, deps):
    after = [[] for _ in range(n)]
    need = [0] * n
    for a, b in deps:
        after[a].append(b)
        need[b] += 1
    ready = [v for v in range(n) if need[v] == 0]
    order = []
    while ready:
        if len(ready) > 1:
            return None
        v = ready.pop()
        order.append(v)
        for w in after[v]:
            need[w] -= 1
            if need[w] == 0:
                ready.append(w)
    return order if len(order) == n else None
